package com.bqsqwad.heartbreakhealer.feature.entertainment

internal object StoryLibraryBatch112 {
    val stories = listOf(
        StorySeries(
            id = "the_bridge_of_borrowed_books",
            title = "The Bridge of Borrowed Books",
            tagline = "Two school libraries create a book exchange that turns a footbridge into a symbol of cooperation.",
            parts = listOf(
                StoryPart(1, "Across the Creek", listOf("A narrow footbridge connected two parts of the town. On one side stood Amina's school, with a small library; on the other was a community learning centre with shelves full of books but few young visitors.", "Amina crossed the bridge with her grandfather and wondered why the two collections never seemed to meet. Her librarian suggested asking the learning centre whether they would like to try a supervised book exchange.", "The idea was simple: books could travel between the buildings, while readers discovered stories and subjects they might never have found otherwise.")),
                StoryPart(2, "A Careful Proposal", listOf("Amina and her class wrote a proposal describing a monthly exchange day. They included a catalogue, a return date, and a plan for adult volunteers to carry the books between the buildings.", "They agreed that no child would need to cross the bridge alone or carry a heavy box. The exchange would happen during supervised opening hours.", "The learning centre replied with enthusiasm and invited the students to a planning meeting.")),
                StoryPart(3, "Choosing the First Books", listOf("The two librarians compared their catalogues and found that each collection had something the other lacked. One had science books for beginners; the other had illustrated history and poetry.", "They chose a small first selection and checked the condition of every book before recording it.", "Amina helped create labels showing the lending library, the return date, and a contact point for questions.")),
                StoryPart(4, "The First Crossing", listOf("On exchange day, adult volunteers carried the books in secure boxes. Students waited at the library tables while the librarians checked each item against the list.", "A few titles had been entered under shortened names, so the team paused to confirm the correct editions rather than guessing.", "The first exchange took longer than expected, but every book arrived safely and the records matched.")),
                StoryPart(5, "A Book Goes Missing", listOf("Two weeks later, one book could not be found on the return shelf. The students worried that the exchange might be cancelled.", "The librarians checked the sign-out records and discovered that the book had been placed on a display table for a reading session. It had not been lost; it had simply not been returned to the correct shelf.", "They updated the return checklist and added a reminder for staff to record books used in group activities.")),
                StoryPart(6, "Stories in Both Places", listOf("The next exchange included a short reading afternoon. A volunteer at the learning centre read a story about a child who built a bridge from recycled materials.", "At Amina's school, students shared a science book about rivers and local wildlife. They asked questions that the two librarians collected for a future guest session.", "The exchange was becoming more than a way to move books. It was helping people discover what their neighbours were learning.")),
                StoryPart(7, "A Rainy Month", listOf("Heavy rain made the footbridge temporarily unavailable. The organisers postponed the exchange rather than asking anyone to use an unsafe route.", "They used the delay to update the catalogue and prepare a list of books that could be reserved for the next date.", "Amina learned that keeping a promise sometimes means changing the schedule when conditions are not suitable.")),
                StoryPart(8, "The Shared Catalogue", listOf("The librarians created a shared digital list that showed each book's title, home collection, and availability. They avoided including children's personal details.", "Students tested the search page and suggested filters for reading level and subject. The librarian reviewed every suggestion before making changes.", "The catalogue made it easier to plan exchanges and reduced the chance of duplicate records.")),
                StoryPart(9, "A Wider Invitation", listOf("The community centre invited families to contribute books in good condition. The librarians explained which kinds were useful and which could not be accepted.", "Donations were checked before being added, and books with missing pages or unsuitable content were set aside for responsible review.", "The shelves grew steadily, but the organisers kept the collection manageable and focused on books readers had requested.")),
                StoryPart(10, "The Bridge Keeps Its Promise", listOf("At the end of the school year, both libraries held a joint celebration. Students displayed reading recommendations and thanked the volunteers who had made the exchange possible.", "Amina placed a small sign beside the bridge-side noticeboard: 'Books travel with care; ideas travel even further.'", "The bridge looked exactly as it had before, but it now connected two busy reading communities. The next exchange date was already written on the calendar."))
            )
        )
    )
}
